    "good": "「这个现象通常是惯量比不对或者刚性过高引起的共振，光调小增益只是把问题按住。建议按官方顺序走一遍：先用离线惯量辨识（面板 H0d.02 就能做，注意机械上要有正反各一圈以上的行程），让驱动器把负载惯量比测准；再用刚性等级做一次自动整定，从当前的 15 级往下试；如果还有固定频率的啸叫，用后台软件的机械特性分析找出共振频率，加陷波器压掉。另外提醒一下，撞限位和压合这类工况不能用在线惯量辨识，得手动设惯量比。」"
