    "text": "警告与故障要分开读。警告级（故障级别 3，可复位）常见的有：**E909.0 电机过载警告、E920.0 制动电阻过载、E922.0 外接制动电阻阻值过小、E730.0 编码器电池警告、E600.0 惯量辨识失败、E950.0 正向超程警告、E952.0 反向超程警告、E120.3 电机与驱动器功率不匹配**。"
