    "text": "看到 E909.0 / E920.0 / E922.0 这类警告不要只做复位。E640.0（IGBT 结温过高）的一条官方原因就是「过载后通过关闭电源对过载故障复位，并反复多次」——警告被反复压下，最后变成硬件级故障。"
