    "text": "**新人自学路径**：先在官网「产品中心 → 工业自动化 → 变频器」把五个二级分类点一遍，把每个分类下的产品列表抄一遍（约 60 多个产品条目），再回到本知识库看选型与参数两篇。这一步做完，客户报需求时你脑子里就有地图了。"
