    "good": "「您这个需求有一台专机就是为拉丝机做的，不用拼几台通用变频器。CL100 系列拉丝机一体机，官网写明是针对拉丝机行业专门定制的驱动器，支持壁挂式安装，产品集成度高，**内置主拉、收线和排线三路变频输出**，对外可提供 DC 24V 输出，可以连接抱闸、触摸屏等设备，另外还内置集成了各种检测和保护电路。软件这块是重点：官网写明产品软件包含有摆杆拉丝机和无摆杆拉丝机工艺包，使用、调试简单；如果您的工艺更复杂，还可以选配 PLC 实现更复杂的工艺；想上数字化，还可以选配汇川物联网模块，做生产数据检视和统计。所以三路输出是内置的，不是三台机器拼起来。我想确认三件事：一是您做的是摆杆机还是无摆杆机，二是主拉/收线/排线的电机功率分别是多少，三是需不需要物联网模块。确认完我给您一台 CL100 加选件的完整清单。」"
