    "bad": "没问题，配个 U 盘就能存。",
    "good": "本地大容量记录建议走 IT9000 高端型：官方数据记录 2000 万条以上、报警 1000 万条以上，配 SD 卡或 U 盘最高可达上亿条，还支持 100 条以上趋势曲线。ITS7000 高防护型规格表里 SD 卡是“不支持”，只能靠网络把数据送出去。另外提醒您，长期记录要设置记录条数上限和循环覆盖策略，用工业级介质，避免卡满后停止记录。"
