    "a": "不能直接比单价，要按「系统总成本」比：本地扩展的模块单价可能更低，但要把点对点的电缆、桥架、电柜空间与装配工时一起算进去；远程方案要加上耦合器 / 主站、电源和附件。**点位越分散、距离越远，远程方案的总成本优势越明显**；反过来，点位集中在柜内附近时，本地扩展更经济。"
